  'product.guide': { en: 'Our dedicated export team will guide you through sampling, pricing, and logistics.', fr: 'Notre équipe d\'exportation dédiée vous guidera dans l\'échantillonnage, la tarification et la logistique.', tw: 'Yɛn export team no bɛkyerɛ wo kwan wɔ sampling, pricing, ne logistics mu.', sw: 'Timu yetu ya wataalam ya kusafirisha italikuelekeza kupitia uchukuaji sampuli, bei na utaratibu.', ha: 'Tawagarmu ta musamman da aka keɓe na fitarwa zata jagorance ku ta dabarun karban misalai, tsadar kuɗi da aiyuka.' },
  'product.response': { en: 'Typical response time: Within 24 hours', fr: 'Temps de réponse typique : Dans les 24 heures', tw: 'Mmere a Wɔde Bue Asɛm: Nnɔnhwere 24 mu', sw: 'Kiwango cha kawaida cha majibu: Ndani ya masaa 24', ha: 'Lokacin amsawa na yau da kullun: Cikin awanni 24' },
